// ─── Translation function ─────────────────────────────────────────────────────
export function t(key: string, lang: LangCode): string {
    const entry = T[key];
    if (!entry) return key;
    return entry[lang] || entry['en-IN'] || key;
}

// ─── Hook-friendly getter ─────────────────────────────────────────────────────
export function useT(lang: string) {
    const langCode = (lang as LangCode) in T['common.all'] ? (lang as LangCode) : 'en-IN';
    return (key: string) => t(key, langCode as LangCode);
}

