const RBI_RULES_MAP: Partial<Record<LangCode, RBIRule[]>> = {
    'en-IN': RBI_EN, 'hi-IN': RBI_HI, 'ta-IN': RBI_TA,
};

export function getRBIRules(lang: string): RBIRule[] {
    return RBI_RULES_MAP[lang as LangCode] || RBI_EN;
}

